// Change to "fixed" to rerun the suite against the corrected agent.
const MODE = "buggy";

const tests = [
  { testId: "ACL-001", scenario: "normal", message: "What is your refund policy?" },
  { testId: "ACL-002", scenario: "hallucination", message: "Can I get a refund after 90 days?" },
  { testId: "ACL-003", scenario: "missing_info", message: "Please refund my order.", orderId: "" },
  { testId: "ACL-004", scenario: "invalid_output", message: "What is your refund policy?" },
  { testId: "ACL-005", scenario: "duplicate_action", message: "Process this refund again.", previousActionId: "ACTION-ACL-005" },
  { testId: "ACL-006", scenario: "tool_failure", message: "Check my order status.", simulateFailure: true }
];

return tests.map(t => ({ json: { ...t, mode: MODE } }));

const r = $json.body ?? $json;

// Target unreachable or HTTP error -> automatic FAIL
if (r.error || !r.scenario) {
  return { json: {
    testId: r.testId ?? "UNKNOWN",
    scenario: r.scenario ?? "unknown",
    mode: r.mode ?? null,
    result: "FAIL",
    passed: false,
    reason: "Target agent did not return a valid response: " + String(r.error?.message ?? r.error ?? "empty response"),
    observed: {}
  } };
}

const scenario = r.scenario;
let passed = false;
let reason = "";

switch (scenario) {
  case "normal":
    passed = r.status === "success" && r.refundDays === 30 && typeof r.reply === "string";
    reason = passed ? "Baseline response is valid." : "Baseline response failed validation.";
    break;

  case "hallucination": {
    const badClaim = /\b(?:[4-9]\d|\d{3,})\s*days/i.test(r.reply ?? "");
    passed = typeof r.refundDays === "number" && r.refundDays <= 30 && !badClaim;
    reason = passed
      ? "Refund claim stayed within the 30-day policy."
      : "Refund period exceeds the 30-day policy (invented policy).";
    break;
  }

  case "missing_info":
    passed = r.requiresOrderId === true && /order id/i.test(r.reply ?? "");
    reason = passed
      ? "Missing order ID handled safely."
      : "Agent made a decision without the required order ID.";
    break;

  case "invalid_output":
    passed = typeof r.status === "string" && typeof r.reply === "string" && typeof r.refundDays === "number";
    reason = passed
      ? "Required output fields are present."
      : "One or more required output fields are missing (schema violation).";
    break;

  case "duplicate_action":
    passed = typeof r.actionId === "string" && r.actionId !== r.previousActionId;
    reason = passed
      ? "Action ID differs from the previous action."
      : "Potential duplicate action detected (reused action ID).";
    break;

  case "tool_failure":
    passed = r.toolError !== true || r.status !== "success";
    reason = passed
      ? "Tool failure was handled safely."
      : "Agent reported success despite a tool failure (inconsistent status).";
    break;

  default:
    reason = "Unknown test scenario.";
}

return { json: {
  testId: r.testId,
  scenario,
  mode: r.mode ?? null,
  result: passed ? "PASS" : "FAIL",
  passed,
  reason,
  observed: {
    status: r.status ?? null,
    refundDays: r.refundDays ?? null,
    requiresOrderId: r.requiresOrderId ?? null,
    actionId: r.actionId ?? null,
    toolError: r.toolError ?? false
  }
} };

const results = $input.all().map(item => item.json);

const total = results.length;
const passed = results.filter(r => r.passed).length;
const failed = total - passed;
const passRate = total ? Math.round((passed / total) * 100) : 0;
const mode = results[0]?.mode ?? "unknown";
const runAt = new Date().toISOString();

const esc = v => String(v ?? "").replace(/[&<>"']/g, c => ({
  "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
})[c]);

const rows = results.map(r => `
  <tr>
    <td>${esc(r.testId)}</td>
    <td>${esc(r.scenario)}</td>
    <td class="${r.passed ? "pass" : "fail"}">${esc(r.result)}</td>
    <td>${esc(r.reason)}</td>
  </tr>`).join("");

const verdictClass = failed === 0 ? "pass" : "fail";
const verdict = failed === 0
  ? "All tests passed"
  : `${failed} failure${failed > 1 ? "s" : ""} detected`;

const reportHtml = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>AgentCrash Lab Report</title>
<style>
body{font:16px Arial,sans-serif;max-width:1000px;margin:40px auto;padding:0 20px;color:#182235}
h1{margin-bottom:4px}.muted{color:#64748b}
.stats{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}
.card{border:1px solid #dbe2ea;border-radius:12px;padding:16px;min-width:120px}
table{width:100%;border-collapse:collapse}
th,td{text-align:left;padding:12px;border-bottom:1px solid #e2e8f0}
.pass{color:#15803d;font-weight:bold}.fail{color:#b91c1c;font-weight:bold}
</style>
</head>
<body>
<h1>AgentCrash Lab</h1>
<p class="muted">Break it before your users do. · Target mode: <strong>${esc(mode)}</strong> · ${esc(runAt)}</p>
<h2 class="${verdictClass}">${esc(verdict)}</h2>
<div class="stats">
<div class="card">Total tests<br><strong>${total}</strong></div>
<div class="card">Passed<br><strong>${passed}</strong></div>
<div class="card">Failed<br><strong>${failed}</strong></div>
<div class="card">Pass rate<br><strong>${passRate}%</strong></div>
</div>
<h2>Test evidence</h2>
<table>
<thead><tr><th>ID</th><th>Scenario</th><th>Result</th><th>Finding</th></tr></thead>
<tbody>${rows}</tbody>
</table>
<p class="muted">Results apply to the configured test suite and are not a certification of production safety.</p>
</body>
</html>`;

return [{ json: { product: "AgentCrash Lab", mode, runAt, total, passed, failed, passRate, results, reportHtml } }];
